cells.push(...[{"id":"anisocytosis","name":"Anisocytosis","group":"Red cells","look":"Visible variation in RBC diameters, rather than an individual abnormal shape.","meaning":"Can reflect immature large RBCs, microcytes or a mixed population; assess reticulocytes and iron status.","why":"A mixture of large and small erythrocytes changes the size distribution, reflected by RDW.","confuse":"Not synonymous with a high MCV; RDW indicates variation, whereas MCV measures the mean.","species":"All mammals","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"acuminocyte","name":"Acuminocyte / fusiform RBC","group":"Red cells","look":"Spindled, pointed or elongated erythrocyte; also called a fusiform cell.","meaning":"Can be physiologic in young goats, some Angora goats and occasional camelids; more numerous in iron-limited camelids.","why":"Hemoglobin polymerization is one possible explanation in species with special hemoglobin variants.","confuse":"Compare with drepanocytes, artifact and elliptocytes.","species":"Goats, camelids","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"aggregateretic","name":"Aggregate reticulocyte","group":"Red cells","look":"Immature anucleate RBC with coarse clumps of residual RNA on supravital new methylene blue staining.","meaning":"Current marrow response to anemia, especially important in cats; use absolute aggregate reticulocyte count.","why":"RNA has not fully degraded following release from bone marrow.","confuse":"Romanowsky smear shows polychromasia; distinguish from punctate reticulocytes with dispersed fine RNA dots.","species":"Dogs, cats","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"basostipple","name":"Basophilic stippling","group":"Red cells","look":"Numerous discrete blue RNA granules distributed through RBC cytoplasm on Romanowsky stain.","meaning":"May accompany regeneration in ruminants or lead toxicity; interpret species and other hematology.","why":"Ribosomal RNA persists due to immaturity or impaired degradation (e.g. lead).","confuse":"Different from a solitary Howell–Jolly body, iron-containing siderocytes or RBC parasites.","species":"Ruminants, dogs","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"dacryocyte","name":"Dacryocyte / teardrop cell","group":"Red cells","look":"RBC stretched to a distinct teardrop outline.","meaning":"May be present in low numbers in camelids; increased numbers can occur in iron deficiency or myelofibrosis.","why":"Mechanism often uncertain; can be associated with marrow disorders and deformability changes.","confuse":"Differentiate from smear-drag artifact and other elongated cells.","species":"Camelids, dogs","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"drepanocyte","name":"Drepanocyte / sickle cell","group":"Red cells","look":"Crescent- or spindle-shaped erythrocyte.","meaning":"Can be a species-related phenomenon in deer and certain small ruminants, not necessarily a hemolytic disorder.","why":"Species-specific hemoglobin polymerization, often after sample collection in certain deer.","confuse":"Do not automatically apply human sickle cell disease mechanisms to deer.","species":"Deer, antelope, some sheep","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"elliptocyte","name":"Elliptocyte","group":"Red cells","look":"RBC elongated into an oval or cigar shape rather than a round disc.","meaning":"Associated with hereditary membrane disorders or marrow fibrosis in some dogs.","why":"May reflect membrane skeleton protein changes or other marrow processes.","confuse":"Camelid oval RBCs are physiologic; don't confuse true elliptocytosis with normal camelid cells.","species":"Dogs; camelid normal oval RBC","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"ghost","name":"Ghost erythrocyte","group":"Red cells","look":"Pale nearly empty membrane outline following loss of hemoglobin.","meaning":"Can accompany hemolysis, e.g. oxidative, infectious, immune or transfusion processes.","why":"Intravascular or in-vitro erythrocyte lysis leaves an RBC membrane remnant.","confuse":"Collection artifact versus true intravascular hemolysis must be differentiated clinically.","species":"All mammals","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"howelljolly","name":"Howell–Jolly body","group":"Red cells","look":"Single, sharply circumscribed dark purple DNA remnant inside an RBC.","meaning":"Low numbers can occur in cats/horses; increased with regeneration or impaired splenic clearance.","why":"Nuclear material remains after erythrocyte maturation and normally can be removed by splenic macrophages.","confuse":"Not a Heinz body, stippling, siderocyte or RBC parasite.","species":"Cats, horses, dogs","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"hypochromic","name":"Hypochromic erythrocyte","group":"Red cells","look":"Erythrocyte with exaggerated central pallor due to reduced hemoglobin concentration.","meaning":"Can support chronic blood loss or iron deficiency; interpret MCHC, MCV, retic Hb and patient history.","why":"Limited hemoglobin synthesis (commonly iron-limited erythropoiesis) produces a pale cell.","confuse":"Torocytes have artifactual sharply punched-out centers; a target cell has central hemoglobin.","species":"Best seen in dogs","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"keratocyte","name":"Keratocyte / blister or horn cell","group":"Red cells","look":"RBC with a blister, one or two horn-like projections or bite-like edge.","meaning":"Can occur with DIC, hemangiosarcoma or oxidative injury, but is not specific.","why":"Membrane damage from mechanical fragmentation or oxidants.","confuse":"Distinguish from the sharper standalone fragments of schistocytes and from eccentrocytes.","species":"Dogs and other mammals","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"macrocyte","name":"Macrocyte","group":"Red cells","look":"Individual RBC larger than surrounding mature cells.","meaning":"Can support regeneration or other hematopoietic/metabolic effects; verify species and breed.","why":"Regeneration (reticulocytes), cell swelling, altered DNA synthesis or other processes.","confuse":"Macrocytes may occur without high mean MCV; compare with punctate reticulocytes.","species":"Dogs/cats","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"poikilocyte","name":"Poikilocytosis","group":"Red cells","look":"Increased variability of RBC SHAPE, including a mixture of distinct abnormal shapes.","meaning":"May be normal in young goats/calves; pathologic significance depends on species and shapes.","why":"Many mechanisms including membrane disease, fragmentation or altered erythropoiesis.","confuse":"Anisocytosis refers to SIZE, not shape.","species":"Young goats/calves","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"polychrom","name":"Polychromatophilic RBC","group":"Red cells","look":"Blue-gray or purple RBC on a Romanowsky-stained blood film.","meaning":"Often evidence of regeneration in dogs/cats, particularly when absolute reticulocyte count rises.","why":"Residual ribosomal RNA in a young RBC stains basophilic and reflects marrow release.","confuse":"Not equivalent to hyperchromasia; usually corresponds to an aggregate reticulocyte.","species":"Dogs/cats","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"punctateretic","name":"Punctate reticulocyte","group":"Red cells","look":"Reticulocyte with fine scattered RNA dots on new methylene blue stain.","meaning":"In cats use aggregate reticulocyte count for current regeneration; punctate counts reflect earlier activity.","why":"More mature than aggregate reticulocytes; residual RNA is mostly degraded.","confuse":"Not a reliable measure of current feline marrow response because cells persist for days.","species":"Cats","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"pyknocyte","name":"Pyknocyte","group":"Red cells","look":"Dense compact erythrocyte remnant associated with oxidant injury.","meaning":"May accompany oxidative hemolysis from toxins or endogenous oxidative stress.","why":"Oxidant-damaged membranes rupture and form small condensed residual cells.","confuse":"May resemble spherocytes; associated eccentrocytes support an oxidant process.","species":"Dogs/cats","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"siderocyte","name":"Siderocyte","group":"Red cells","look":"RBC containing focal iron-bearing blue-gray granules (Pappenheimer bodies).","meaning":"Can occur with hemolysis, marrow dysplasia, metabolic disorders or lead-associated disease.","why":"Intracellular iron aggregates arise with increased turnover or altered iron utilization.","confuse":"Distinguish from basophilic stippling by focal dots and Prussian-blue iron staining.","species":"Various mammals","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"stomatocyte","name":"Stomatocyte","group":"Red cells","look":"RBC with slit-shaped or mouth-shaped central pallor.","meaning":"Persistent forms may accompany inherited disorders or drug effects in dogs.","why":"Inner membrane leaflet expansion changes the discocyte into a cup-shaped form.","confuse":"Can be smear artifact in thick areas; compare with spherocytes and target cells.","species":"Dogs","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"target","name":"Target cell / codocyte","group":"Red cells","look":"Bullseye RBC with central spot of hemoglobin surrounded by a pallor ring and peripheral hemoglobin.","meaning":"Can accompany iron deficiency or hepatobiliary/lipid abnormalities in dogs.","why":"Excess membrane relative to cell volume alters hemoglobin distribution on smear.","confuse":"Compare with torocytes (sharply punched-out artifact) and hypochromic RBC.","species":"Dogs","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"torocyte","name":"Torocyte","group":"Red cells","look":"RBC with a sharply punched-out pallor zone, frequently eccentrically located.","meaning":"Usually not reported as diagnostic disease morphology.","why":"Primarily a blood-film preparation artifact.","confuse":"Differs from diffuse increased central pallor of a true hypochromic RBC.","species":"Blood film artifact","url":"https://eclinpath.com/hematology/morphologic-features/red-blood-cells/quick-guide/"},{"id":"hemediff","name":"Hematuria vs hemoglobinuria vs myoglobinuria","group":"Platelets and artifacts","look":"Dipstick heme positive in all three; urine sediment, centrifugation and plasma/CK distinguish.","meaning":"Hematuria often yields urine RBCs. Intravascular hemolysis causes free plasma Hb and anemia; myoglobinuria accompanies severe muscle injury and high CK.","why":"Urinary bleeding releases cells, intravascular hemolysis releases hemoglobin and rhabdomyolysis releases myoglobin.","species":"All species; check USG, urine pH and storage","url":"https://eclinpath.com/urinalysis/chemical-constituents/"},{"id":"lysedrbc","name":"RBCs lysed after entering urine","group":"Platelets and artifacts","look":"Heme-positive urine with ghost cells or no RBCs in dilute, alkaline or old urine.","meaning":"Can resemble true hemoglobinuria, but may simply represent hematuria with urinary RBC lysis.","why":"Urine osmolality and pH damage RBC membranes; this is not inherently intravascular hemolysis.","species":"All","url":"https://eclinpath.com/urinalysis/cellular-constituents/"},{"id":"methemoglobin","name":"Methemoglobin pigment (brown urine)","group":"Platelets and artifacts","look":"Brown or reddish-brown urine with or without intact RBCs.","meaning":"Oxidized hemoglobin causes brown pigment; brown urine does not establish myoglobinuria.","why":"Hemoglobin ferrous iron (Fe2+) oxidizes to ferric iron (Fe3+).","species":"All","url":"https://eclinpath.com/urinalysis/chemical-constituents/"}]);
